# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DIŞ DÜNYADAN (ÂFÂK) HAREKET EDEN DELİLLER</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">GAYE VE NİZAM (TELEOLOJİK) DELİLİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• Nizam: Evrendeki hassas ölçü, yasa, denge ve uyum.</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• Gaye: Hiçbir varlığın boşuna ve amaçsız yaratılmaması.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• İnayet (İbn Rüşd): Evrenin insan yaşamına uygunluğu.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• Ayet: \'Biz her şeyi bir ölçüye göre yarattık\' (Kamer, 49).</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• Sonuç: Düzen; ilim, irade ve kudret sahibi Yaratıcıyı gösterir.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">HUDÛS, İMKÂN VE İHTİRA DELİLLERİ</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• Hudûs: Sonradan var olan (hâdis) her şeyin Yaratıcısı vardır.</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• İmkân: Mümkün varlıklar, Zorunlu Varlığa (Vâcibü\'l-Vücûd) muhtaçtır.</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• İhtira (İbn Rüşd): Varlıkların yoktan ve benzersiz yaratılması.</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• Nedensellik: Teselsül (sonsuz zincir) aklen imkânsızdır.</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Sonuç: Ezeli ve ebedi olan ilk sebep Yüce Allah\'tır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Kur\'an-ı Kerim, insanı göklerin ve yerin yaratılışındaki ayetleri (işaretleri) tefekkür etmeye davet eder.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İÇ DÜNYADAN (ENFÜS) HAREKET EDEN DELİLLER</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">EKMEL VARLIK (ONTOLOJİK) DELİLİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• Çıkış Noktası: Zihindeki \'En Mükemmel Varlık\' düşüncesi.</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• İnsan sınırlı, ölümlü ve eksik bir varlıktır.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• Eksik olan insan, mutlak mükemmellik fikrini uyduramaz.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• Gerçekten var olmamak bir eksiklik olacağından;</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• En yetkin (Ekmel) varlık olan Allah zorunlu olarak vardır.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">FITRAT VE KABUL-İ ÂMME DELİLİ</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• Fıtrat: İnsanın doğuştan getirdiği tevhit ve inanma özü.</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• Ayet: \'Allah\'ın insanları üzerinde yarattığı fıtrat\' (Rûm, 30).</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• Elest Bezmi: Ruhların \'Belâ\' ikrarı (A\'râf, 172).</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Zorluk anında insanın samimiyetle Allah\'a sığınması.</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• Kabul-i Âmme: Tarih boyu tüm toplumlarda inancın varlığı.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Fıtrat ve Ekmel Varlık delilleri, Allah inancının insanın ruhuna ve zihnine kodlanmış olduğunu gösterir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ALLAH\'IN (CC) BİRLİĞİNİN DELİLİ: BURHÂN-I TEMÂNU (TEVHİT)</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">BURHÂN-I TEMÂNU (ENGELLEME DELİLİ)</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Varsayım: Evrende birden fazla ilah olsaydı ne olurdu?</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• Durum: İlahların iradeleri ve hükümleri çatışırdı.</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• Sonuç 1: İkisinin de iradesinin olmaması -&gt; Acizliktir.</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Sonuç 2: Yalnız birinin iradesinin olması -&gt; Tek İlah vardır.</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Sonuç 3: Evrendeki mükemmel uyum bozulur, kaos çıkardı.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">KUR\'AN-I KERİM\'DE TEVHİT VURGUSU</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• Enbiyâ 22: \'Allah\'tan başka ilahlar olsaydı düzen bozulurdu.\'</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• Mü\'minûn 91: \'Her ilah kendi yarattığını alıp götürürdü.\'</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• İhlâs 1-4: \'De ki: O Allah\'tır, bir tektir (Ehad).\'</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Kozmik Birlik: Doğa yasalarının evrenin her yerinde aynı olması.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• Tevhit: Allah\'ın zatında, sıfatlarında ve fiillerinde tekliği.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Evrende hiçbir karmaşa olmaması ve düzenin kesintisiz sürmesi, Yaratıcı\'nın bir ve tek (Vâhid/Ehad) olduğunu kanıtlar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
